using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using Jindan.Contracts;
using Jindan.Core;
using Jindan.Desktop.Contracts;
using Jindan.Infrastructure;
using Jindan.Modules.Files;

static class Program
{
    static int pass, fail; static bool completed; static readonly List<object> tests = []; static string output = "";
    static string Hash(byte[] data) => Convert.ToHexStringLower(SHA256.HashData(data));
    static void Assert(bool value, string message) { if (!value) throw new Exception(message); }
    static async Task Test(string name, Func<Task> action) { try { await action(); pass++; tests.Add(new { name, pass = true }); Console.WriteLine("PASS " + name); } catch (Exception error) { fail++; tests.Add(new { name, pass = false, error = error.ToString() }); Console.WriteLine("FAIL " + name + ": " + error.Message); } }
    static string[] Entries(string file) { using var zip = ZipFile.OpenRead(file); return zip.Entries.Select(e => e.FullName).ToArray(); }
    [STAThread] static int Main(string[] args)
    {
        ApplicationConfiguration.Initialize(); output = Path.GetFullPath(args.FirstOrDefault() ?? throw new Exception("Fresh output required")); Assert(!Directory.Exists(output), "Fresh output required"); Directory.CreateDirectory(output); bool expectOld = args.Contains("--expect-old"); var installation = args.FirstOrDefault(a => a.StartsWith("--installation="))?[15..]; var loaded = new List<object>();
        foreach (var pair in new (Type Type, string Path)[] { (typeof(WorkRecord), "Jindan.Contracts.dll"), (typeof(DomainRules), "Jindan.Core.dll"), (typeof(RecordDocument), "Jindan.Desktop.Contracts.dll"), (typeof(LocalWorkspace), "Jindan.Infrastructure.dll"), (typeof(FileDocument), "modules/files/Jindan.Modules.Files.dll") }) { var hash = Hash(File.ReadAllBytes(pair.Type.Assembly.Location)); if (installation is not null) Assert(hash == Hash(File.ReadAllBytes(Path.Combine(installation, pair.Path))), "Exact installation differs: " + pair.Path); loaded.Add(new { path = pair.Path, sha256 = hash }); }
        using var store = new LocalWorkspace(Path.Combine(output, "data")); var actor = store.BootstrapAsync("Archive synthetic", "archive-local-70-test", true).GetAwaiter().GetResult(); store.RegisterSchema(new("projects", "Projects", [new("title", "Title", Required: true)], false)); var assets = new HookAssets(store); var services = new Services(actor, store, assets); var module = new Jindan.Modules.Files.Module(); module.Initialize(services);
        var p = store.SaveAsync(actor, new(null, "projects", null, 0, new() { ["title"] = "격리 선택 ZIP" })).GetAwaiter().GetResult(); var q = store.SaveAsync(actor, new(null, "projects", null, 0, new() { ["title"] = "격리 이름 충돌" })).GetAwaiter().GetResult(); var context = new DocumentContext("selection-probe70", "files", p.Id, actor.Id); using var form = new Form { Text = "선택 ZIP 경계 합성 시험", Width = 1000, Height = 700 }; using var files = new FileDocument(services, module.Schema, context); form.Controls.Add(files);
        form.Shown += async (_, _) =>
        {
            try
            {
                await files.Ready; Directory.CreateDirectory(Path.Combine(store.DataRoot, "exports")); var source = Path.Combine(output, "source.txt"); await File.WriteAllTextAsync(source, "SYNTHETIC immutable original bytes"); var first = await files.ImportPathAsync(source); var aliasPath = Path.Combine(output, "chosen-alias.txt"); File.Copy(source, aliasPath); var alias = await files.ImportPathAsync(aliasPath); var hiddenPath = Path.Combine(output, "must-not-export.txt"); await File.WriteAllTextAsync(hiddenPath, "SYNTHETIC unselected data"); var unselected = await files.ImportPathAsync(hiddenPath);
                await Test("selected archive validates bytes after authorized asset metadata before copy", async () => { var original = await store.GetAsync(actor, first.Fields["assetId"]); var originalBytes = await File.ReadAllBytesAsync(original.StoredPath); var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip", SearchOption.TopDirectoryOnly).Length;
                    assets.AfterGet = async (value, call) => { if (call == 1) await File.WriteAllTextAsync(value.StoredPath, "SYNTHETIC changed after verified GetAsync"); }; assets.Reset(); string? result = null; bool rejected = false; try { try { result = await files.ExportSelectionZipAsync([first.Id]); } catch (Exception error) when (error is InvalidDataException || error is WorkspaceException { Code: "CORRUPT_ASSET" }) { rejected = true; } if (expectOld) { Assert(!rejected && result is not null, "Old selected-copy defect did not reproduce"); using var zip = ZipFile.OpenRead(result!); using var entry = zip.Entries.Single(e => e.FullName.StartsWith("files/")).Open(); var actual = Convert.ToHexStringLower(SHA256.HashData(entry)); Assert(actual != original.Sha256, "Archive unexpectedly matches metadata"); await File.WriteAllTextAsync(Path.Combine(output, "OLD_SELECTED_SHA_MISMATCH.json"), JsonSerializer.Serialize(new { output = result, expectedSha256 = original.Sha256, actualSha256 = actual, findingConfirmed = true, productionSuccess = false })); } else { Assert(rejected, "Changed bytes were published"); Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before, "Rejected selection left published ZIP"); } } finally { assets.AfterGet = null; await File.WriteAllBytesAsync(original.StoredPath, originalBytes); } });
                await Test("selected aliases preserve chosen title and immutable original name without unselected data", async () => { var path = await files.ExportSelectionZipAsync([alias.Id, alias.Id]); var names = Entries(path); var chosen = names.Single(x => x.StartsWith("files/")); if (expectOld) Assert(!chosen.EndsWith("chosen-alias.txt", StringComparison.Ordinal), "Old alias-name loss did not reproduce"); else { Assert(chosen.EndsWith("chosen-alias.txt", StringComparison.Ordinal) && !names.Any(x => x.EndsWith("must-not-export.txt", StringComparison.Ordinal)), "Selected alias or subset lost"); using var zip = ZipFile.OpenRead(path); using var manifest = zip.GetEntry("manifest.json")!.Open(); using var document = await JsonDocument.ParseAsync(manifest); var entry = document.RootElement.GetProperty("files").EnumerateArray().Single(); Assert(entry.GetProperty("title").GetString() == "chosen-alias.txt" && entry.GetProperty("OriginalName").GetString() == "source.txt", "Alias/original provenance missing"); } Assert(first.Fields["assetId"] == alias.Fields["assetId"], "Alias duplicated immutable asset"); });
                await Test("same-named sibling file and folder never share an extraction path", async () => { files.SetContext(context with { ProjectId = q.Id }); await files.RefreshAsync(); var filePath = Path.Combine(output, "A"); await File.WriteAllTextAsync(filePath, "SYNTHETIC same-named sibling"); await files.ImportPathAsync(filePath); await files.CreateFolderAsync("A"); var path = await files.ExportFolderZipAsync(""); var names = Entries(path).Where(x => x != "manifest.json").ToArray(); var normalized = names.Select(x => x.TrimEnd('/')).ToArray(); var collisions = normalized.Length != normalized.Distinct(StringComparer.OrdinalIgnoreCase).Count(); Assert(collisions == expectOld, expectOld ? "Old extraction collision did not reproduce" : "Sibling file/folder extraction collision remains"); await File.WriteAllTextAsync(Path.Combine(output, expectOld ? "OLD_SIBLING_COLLISION.json" : "SIBLING_PATHS.json"), JsonSerializer.Serialize(new { names, collisions, expectOld })); files.SetContext(context); await files.RefreshAsync(); });
                if (!expectOld)
                {
                    await Test("two selected aliases stay separate while sharing original asset bytes", async () => { var path = await files.ExportSelectionZipAsync([first.Id, alias.Id]); using var zip = ZipFile.OpenRead(path); var members = zip.Entries.Where(e => e.FullName.StartsWith("files/")).ToArray(); Assert(members.Length == 2 && members.Any(e => e.Name.EndsWith("source.txt", StringComparison.Ordinal)) && members.Any(e => e.Name.EndsWith("chosen-alias.txt", StringComparison.Ordinal)), "Selected aliases collapsed"); foreach (var member in members) { using var stream = member.Open(); Assert(Convert.ToHexStringLower(SHA256.HashData(stream)) == first.Fields["sha256"], "Alias content changed"); } });
                    await Test("selected archive rejects unknown IDs and preserves exact chosen count", async () => { var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; try { await files.ExportSelectionZipAsync([alias.Id, "not-authorized"]); throw new Exception("Unknown selection accepted"); } catch (InvalidOperationException) { } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before, "Invalid selection published output"); });
                    await Test("selected stage context switch and late cancel cannot publish", async () => { foreach (var cancelInstead in new[] { false, true }) { assets.Reset(); var entered = new TaskCompletionSource(); var release = new TaskCompletionSource(); assets.AfterGet = async (_, call) => { if (call == 2) { entered.SetResult(); await release.Task; } }; using var cancellation = new CancellationTokenSource(); var before = Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length; var request = files.ExportSelectionZipAsync([alias.Id], cancellation.Token); var next = await Task.WhenAny(entered.Task, request).WaitAsync(TimeSpan.FromSeconds(10)); if (next == request) { await request; throw new Exception("Expected publication-phase pause"); } if (cancelInstead) cancellation.Cancel(); else files.SetContext(context with { ProjectId = q.Id }); release.SetResult(); try { await request; throw new Exception("Stale selected stage published"); } catch (OperationCanceledException) when (cancelInstead) { } catch (InvalidOperationException) when (!cancelInstead) { } finally { assets.AfterGet = null; files.SetContext(context); await files.RefreshAsync(); } Assert(Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), "*.zip").Length == before && !Directory.GetFiles(Path.Combine(store.DataRoot, "exports"), ".folder-stage-*.tmp").Any(), "Failed selected stage left output"); } });
                }
            }
            catch (Exception error) { fail++; tests.Add(new { name = "setup", pass = false, error = error.ToString() }); }
            finally { await File.WriteAllTextAsync(Path.Combine(output, "RESULT.json"), JsonSerializer.Serialize(new { pass, fail, expectOld, meaning = expectOld ? "Expected pre-fix failures reproduced, not product success" : "Fixed synthetic regression", loaded, tests, reportReady = false, supervisorAccepted = false }, new JsonSerializerOptions { WriteIndented = true })); completed = true; form.Close(); }
        };
        Application.Run(form); Console.WriteLine($"FILES_ARCHIVE70 pass={pass} fail={fail} old={expectOld} completed={completed}"); return completed && fail == 0 ? 0 : 1;
    }
    sealed class HookAssets(IAssetService inner) : IAssetService { int calls; public Func<AssetInfo, int, Task>? AfterGet { get; set; } public void Reset() => calls = 0; public async Task<AssetInfo> GetAsync(Identity actor, string id, CancellationToken ct = default) { var value = await inner.GetAsync(actor, id, ct); if (AfterGet is not null) await AfterGet(value, ++calls); return value; } public Task<AssetInfo> ImportAsync(Identity actor, string p, string path, CancellationToken ct = default) => inner.ImportAsync(actor, p, path, ct); public Task ExportAsync(Identity actor, string id, string path, CancellationToken ct = default) => inner.ExportAsync(actor, id, path, ct); }
    sealed class Services(Identity actor, LocalWorkspace store, IAssetService assets) : IWorkspaceServices { public Identity Actor => actor; public IWorkspaceData Data => store; public IIdentityService Identities => store; public IAssetService Assets => assets; public ILayoutStore Layout => store; public string DataRoot => store.DataRoot; public IReportService Reports { get; } = new NoReport(); }
    sealed class NoReport : IReportService { public Task<ReportReply> ExecuteAsync(DocumentContext c, ReportCommand m, IProgress<ReportProgress>? p = null, CancellationToken ct = default) => throw new NotSupportedException(); public Task AcknowledgeReviewAsync(DocumentContext c, string s, string f, string r, CancellationToken ct = default) => throw new NotSupportedException(); public void Invalidate(string id) { } }
}
